            entity.setNextBillingDate( event.getNextBillingDate() );
            entity.setStartDate( event.getStartDate() );
            entity.setEndDate( event.getEndDate() );
            entity.setCustomer( event.getCustomer() );
            entity.setVariant( event.getVariant() );
            entity.setPaymentProvider( event.getPaymentProvider() );
            entity.setChannel( event.getChannel() );
            entity.setStatus( event.getStatus() );
            entity.setInterval( event.getInterval() );
 
    	// ------------------------------------------
